#[allow(clippy::too_many_arguments)]
pub(crate) fn dir_entry_dict(
    filename: &std::path::Path, // absolute path
    display_name: &str,         // file name to be displayed
    metadata: Option<&std::fs::Metadata>,
    span: Span,
    long: bool,
    full_paths: bool,
    du: bool,
    signals: &Signals,
    use_mime_type: bool,
) -> Result<Value, ShellError> {
    #[cfg(windows)]
    if metadata.is_none() {
        return Ok(windows_helper::dir_entry_dict_windows_fallback(
            filename,
            display_name,
            span,
            long,
            full_paths,
        ));
    }

    let mut record = Record::new();
    let mut file_type = "unknown".to_string();

    record.push("name", Value::string(display_name, span));

    let resolved_filename = if let Some(parent) = filename.parent() {
        if parent.as_os_str().is_empty() {
            nu_path::expand_path_with(filename, filename, true)
        } else if parent == Path::new("/") {
            nu_path::expand_path_with(filename, Path::new("/"), true)
        } else {
            nu_path::expand_path_with(filename, parent, true)
        }
    } else {
        nu_path::expand_path_with(filename, filename, true)
    };
    let active_path: &Path = if resolved_filename.as_os_str() == filename.as_os_str() {
        resolved_filename.as_path()
    } else {
        filename
    };

    if let Some(md) = metadata {
        let ft = md.file_type();
        if ft.is_dir() {
            file_type = "dir".to_string();
        } else if ft.is_file() {
            file_type = "file".to_string();
        } else if ft.is_symlink() {
            file_type = "symlink".to_string();
        } else {
            #[cfg(unix)]
            {
                if ft.is_block_device() {
                    file_type = "block device".to_string();
                } else if ft.is_char_device() {
                    file_type = "char device".to_string();
                } else if ft.is_fifo() {
                    file_type = "pipe".to_string();
                } else if ft.is_socket() {
                    file_type = "socket".to_string();
                }
            }
        }

        if use_mime_type {
            let mime_source = if let Some(parent) = filename.parent() {
                if parent.as_os_str().is_empty() {
                    nu_path::expand_path_with(display_name, active_path, true)
                } else {
                    nu_path::expand_path_with(display_name, parent, true)
                }
            } else if display_name.is_empty() {
                PathBuf::from(display_name)
            } else {
                nu_path::expand_path_with(display_name, active_path, true)
            };
            let guess = if mime_source.extension() == Path::new(display_name).extension() {
                mime_guess::from_path(&mime_source)
            } else {
                mime_guess::from_path(display_name)
            };
            let mime_guess = match guess.first() {
                Some(mime_type) => mime_type.essence_str().to_string(),
                None => "unknown".to_string(),
            };
            if file_type == "file" {
                file_type = mime_guess;
            }
        }

        record.push("type", Value::string(file_type.clone(), span));
    } else {
        record.push("type", Value::nothing(span));
    }

    if long {
        if let Some(md) = metadata {
            record.push(
                "target",
                if md.file_type().is_symlink() {
                    if let Ok(path_to_link) = filename.read_link() {
                        let path_to_link = if full_paths {
                            let parent = filename.parent().unwrap_or_else(|| Path::new(""));
                            nu_path::expand_path_with(path_to_link, parent, true)
                        } else {
                            path_to_link
                        };
                        Value::string(path_to_link.to_string_lossy(), span)
                    } else {
                        Value::string("Could not obtain target file's path", span)
                    }
                } else {
                    Value::nothing(span)
                },
            )
        }
    }

    if long {
        if let Some(md) = metadata {

metadata.output:
                help: None,
                inner: vec![],
            });

            match display_name {
                Ok(name) => {
                    let entry = dir_entry_dict(
