                        call_span,
                        long,
                        full_paths,
                        du,
                        &signals,
                        use_mime_type,
                    );
                    match entry {
                        Ok(value) => Some(value),
                        Err(err) => Some(Value::error(err, call_span)),
                    }
                }
                Err(err) => Some(Value::error(err, call_span)),
            }
        }
        Err(err) => Some(Value::error(err, call_span)),
}

